  // local envelope parser before any bytes are sealed as evidence.
  const nonBlankString = { type: 'string' };
  const stringArray = { type: 'array', items: { type: 'string' } };
  const digest = { type: 'string' };
  const readManifest = {
    type: 'object',
    additionalProperties: false,
